// Contracts the webhooks application depends on; `infrastructure/` provides
// the real ones and tests may replace them. Nest injects each by its class.

import { v7 } from 'uuid';

/** A new UUID v7 for a webhooks row, generated by the application. */
export function newWebhookId(): string {
  return v7();
}

/** The time, replaceable in tests. */
export abstract class WebhooksClock {
  abstract now(): Date;
}

export class SystemWebhooksClock extends WebhooksClock {
  now(): Date {
    return new Date();
  }
}

/** An encrypted value and the id of the key that sealed it. */
export interface SealedSecret {
  readonly ciphertext: string;
  readonly keyId: string;
}

/** Seals and opens signing secrets at rest. */
export abstract class SecretCipher {
  abstract encrypt(plaintext: string): SealedSecret;
  abstract decrypt(sealed: SealedSecret): string;
}

/** One attempt of one delivery: its first attempt is number 1. */
export interface DeliveryAttemptRef {
  readonly deliveryId: string;
  readonly attempt: number;
}

/**
 * Hands deliveries to a background worker. Each attempt has its own job id,
 * derived from the delivery id and the attempt number, so handing the same
 * attempt over twice runs it once.
 */
export abstract class DeliveryDispatcher {
  /** First attempts, now. */
  abstract dispatch(deliveryIds: readonly string[]): Promise<void>;
  /** A retry, to run at `at`. */
  abstract schedule(ref: DeliveryAttemptRef, at: Date): Promise<void>;
  /**
   * Attempts that are due by PostgreSQL's account: runs each now, whether its
   * job is waiting for a later time, ended without an attempt, or was lost.
   */
  abstract redispatch(refs: readonly DeliveryAttemptRef[]): Promise<void>;
}

/** Uniform random numbers in [0, 1) for the retry jitter. */
export abstract class RetryJitter {
  abstract next(): number;
}

export class MathRetryJitter extends RetryJitter {
  next(): number {
    return Math.random();
  }
}

export interface OutboundRequest {
  readonly url: string;
  readonly headers: Readonly<Record<string, string>>;
  readonly body: string;
}

export interface OutboundResult {
  /** Null when no HTTP answer came. */
  readonly httpStatus: number | null;
  readonly durationMs: number;
  readonly responseBody: string | null;
  /** Why no 2xx answer came: refused address, timeout, network error, status. */
  readonly error: string | null;
}

/**
 * POSTs one Webhook. It applies the outbound policy (SSRF protection), never
 * follows a redirect and gives up after the configured timeout. It never
 * throws for a failed delivery; the result says what happened.
 */
export abstract class WebhookSender {
  abstract post(request: OutboundRequest): Promise<OutboundResult>;
}

/**
 * Checks a Webhook Endpoint URL when it is saved: the same rules a delivery
 * applies, DNS resolution included. Resolves to why it is refused, or null.
 */
export abstract class WebhookUrlGuard {
  abstract check(url: string): Promise<string | null>;
}
